-- Repair journal triggers installed by 0062; preserve durable events/cursors.
DROP TRIGGER IF EXISTS fed_journal_update;
CREATE TRIGGER IF NOT EXISTS fed_journal_update AFTER UPDATE ON memories WHEN ((OLD.federation_source IS NULL AND (OLD.namespace IS NULL OR OLD.namespace<>'vault')) OR (NEW.federation_source IS NULL AND (NEW.namespace IS NULL OR NEW.namespace<>'vault'))) AND (OLD.federation_source IS NOT NEW.federation_source OR OLD.content IS NOT NEW.content OR OLD.category IS NOT NEW.category OR OLD.subcategory IS NOT NEW.subcategory OR OLD.namespace IS NOT NEW.namespace OR OLD.owner_id IS NOT NEW.owner_id OR OLD.permission_mode IS NOT NEW.permission_mode OR OLD.deleted_at IS NOT NEW.deleted_at OR OLD.archived_at IS NOT NEW.archived_at OR OLD.consolidated_into IS NOT NEW.consolidated_into OR OLD.updated IS NOT NEW.updated OR OLD.embedding IS NOT NEW.embedding OR OLD.metadata IS NOT NEW.metadata OR OLD.verbatim_content IS NOT NEW.verbatim_content OR OLD.source_model IS NOT NEW.source_model OR OLD.source_provider IS NOT NEW.source_provider OR OLD.source_agent IS NOT NEW.source_agent OR OLD.source_session IS NOT NEW.source_session)
BEGIN
 INSERT INTO federation_changes(memory_id,changed_at,old_namespace,old_category,old_public,old_exportable,new_namespace,new_category,new_public,new_exportable) SELECT NEW.id,strftime('%Y-%m-%dT%H:%M:%f+00:00','now'),OLD.namespace,OLD.category,CASE WHEN (OLD.permission_mode % 10)>=4 THEN 1 ELSE 0 END,CASE WHEN OLD.federation_source IS NULL AND (OLD.namespace IS NULL OR OLD.namespace<>'vault') AND OLD.deleted_at IS NULL AND OLD.archived_at IS NULL AND OLD.consolidated_into IS NULL THEN 1 ELSE 0 END,NEW.namespace,NEW.category,CASE WHEN (NEW.permission_mode % 10)>=4 THEN 1 ELSE 0 END,CASE WHEN NEW.federation_source IS NULL AND (NEW.namespace IS NULL OR NEW.namespace<>'vault') AND NEW.deleted_at IS NULL AND NEW.archived_at IS NULL AND NEW.consolidated_into IS NULL THEN 1 ELSE 0 END;
END;

INSERT OR REPLACE INTO schema_marker(name,applied) VALUES('0064_federation_journal_dialects.sql',1);
